// roteirista-cirl — Gera roteiro estruturado por cenas + prompts de avatar em inglês
// Input: { production_id, topic }
// Output: { production_id, topic, scenes[], intro_prompt, outro_prompt }

const https = require('https');

const MINIMAX_API_KEY = "sk-cp-VfL7mdXRnwrcaoTwahYjER-M4zE-J3vErRxKyPD8QYKeQDmYwgX_DNl8ZA7HHJQ0EtDteBfhCBncD0nBxBa_mWAyb_8stH4WcQ3iXQ-54BVzTucNv0qZRXU";
const MINIMAX_GROUP_ID = "2041519126085645203";

const body = $input.first().json.body || $input.first().json;
const pid   = body.production_id;
const topic = body.topic;

if (!topic) throw new Error('topic is required');

const SYSTEM_PROMPT = `Você é roteirista especializado em conteúdo de nutrição e saúde para short-form video (TikTok/Reels/Shorts).

Gere um roteiro para o canal da nutricionista Cirlene Niza sobre o tema fornecido.

REGRAS GERAIS:
- Duração total: 45-60 segundos de narração
- 3 a 5 cenas de conteúdo (slides)
- Tom: científico mas acessível, direto, confiante
- TODOS os textos das cenas em português brasileiro — sem exceção
- Fontes: cite revistas científicas reais (NEJM, Lancet, JAMA, Nutrients, etc.)

LAYOUTS DISPONÍVEIS — schemas EXATOS (campos diferentes = crash):
- StatCard:             { layout, stat:string, description:string, source:string, topic:string, narration:string }
- CircleStat:           { layout, value:number, unit:string, description:string, source:string, topic:string, narration:string }
- ComparisonBar:        { layout, title:string, before:{label:string,value:number}, after:{label:string,value:number}, unit:string, source:string, narration:string }
- StudyQuote:           { layout, quote:string, highlight:string, study:string, year:number, topic:string, narration:string }
- BenefitsList:         { layout, title:string, items:[{icon:string,text:string}], source:string, topic:string, narration:string }
- TimelineProgress:     { layout, title:string, milestones:[{label:string,value:string,description:string}], source:string, topic:string, narration:string }
- ScientificDefinition: { layout, term:string, definition:string, analogy:string, topic:string, narration:string }

CAMPO narration (obrigatório em todas as cenas):
- Texto que a apresentadora vai FALAR em voz alta enquanto o slide aparece
- Em português brasileiro coloquial e fluente
- 2-3 frases, 10-15 segundos de fala
- Deve complementar o visual, não repetir exatamente o que está escrito
- Exemplo: "A creatina é um dos suplementos mais estudados da ciência. Ela age diretamente nas suas células musculares, dando mais energia pra você treinar com mais força e mais intensidade."

ATENÇÃO: NÃO use campos que não estão na lista acima. Ex: ComparisonBar NÃO tem "items", TimelineProgress NÃO tem "steps".

FORMATO DE RESPOSTA (JSON puro, sem markdown):
{
  "scenes": [ ...array de cenas com narration em PT-BR... ],
  "intro_narration": "...",
  "outro_narration": "...",
  "intro_prompt": "...",
  "outro_prompt": "..."
}

CAMPO intro_narration e outro_narration:
- Texto PT-BR que a apresentadora fala na intro/outro
- intro: saudação + apresentação do tema (10-15s)
- outro: chamada para seguir o canal + encerramento (8-10s)
- Exemplo intro: "Oi gente! Hoje vou te mostrar por que a creatina é o suplemento mais poderoso que você pode tomar todo dia."

REGRAS para intro_prompt e outro_prompt (prompt para IA de vídeo Veo — MUITO IMPORTANTE):
- O prompt DEVE incluir o texto exato da fala em português, entre aspas simples
- Isso faz o Veo gerar áudio em português naturalmente — é a chave para PT-BR funcionar
- NÃO use "Brazilian" nem nome próprio (content filter bloqueia)
- Visual: "A nutritionist with dark hair and a warm smile, professional indoor setting"
- FORMATO OBRIGATÓRIO: "A nutritionist with dark hair and a warm smile looks directly at camera and says: '[cole aqui o texto do intro_narration/outro_narration em PT-BR]'. Professional indoor setting, bright lighting."
- EXEMPLO intro_prompt: "A nutritionist with dark hair and a warm smile looks directly at camera and says: 'Oi pessoal! Hoje vou te mostrar por que a creatina é o suplemento mais poderoso que você pode tomar todo dia.' Professional indoor setting, bright lighting."
- EXEMPLO outro_prompt: "A nutritionist with dark hair and a warm smile waves to camera and says: 'Gostou? Segue o canal pra mais dicas de nutrição baseadas em ciência!' Professional indoor setting."
- O texto entre aspas simples DEVE ser exatamente igual ao intro_narration / outro_narration
- Máximo 3 frases no total do prompt`;

function minimax(messages) {
  return new Promise((resolve, reject) => {
    const payload = JSON.stringify({
      model: 'MiniMax-Text-01',
      messages,
      temperature: 0.7,
      max_tokens: 2048,
    });
    const opts = {
      hostname: 'api.minimaxi.chat',
      path: `/v1/text/chatcompletion_v2?GroupId=${MINIMAX_GROUP_ID}`,
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${MINIMAX_API_KEY}`,
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload),
      },
    };
    const req = https.request(opts, res => {
      let data = '';
      res.on('data', c => data += c);
      res.on('end', () => {
        try { resolve(JSON.parse(data)); }
        catch(e) { resolve({ raw: data }); }
      });
    });
    req.on('error', reject);
    req.write(payload);
    req.end();
  });
}

console.log(`[${pid}] Gerando roteiro para: "${topic}"`);

const resp = await minimax([
  { role: 'system', content: SYSTEM_PROMPT },
  { role: 'user', content: `Tema: ${topic}\nProduction ID: ${pid}` },
]);

if (resp.raw) throw new Error('MiniMax retornou resposta inválida: ' + resp.raw.slice(0, 200));
if (resp.base_resp && resp.base_resp.status_code !== 0) {
  throw new Error('MiniMax error: ' + JSON.stringify(resp.base_resp));
}

const text = resp.choices?.[0]?.message?.content || resp.choices?.[0]?.text || '';
if (!text) throw new Error('MiniMax: resposta vazia. Keys: ' + Object.keys(resp).join(', '));

console.log(`[${pid}] Resposta MiniMax (${text.length} chars)`);

// Parse JSON — remove possíveis blocos markdown
const jsonText = text.replace(/^```json?\n?/m, '').replace(/\n?```$/m, '').trim();
let roteiro;
try {
  roteiro = JSON.parse(jsonText);
} catch(e) {
  throw new Error('Falha ao parsear JSON do MiniMax: ' + jsonText.slice(0, 300));
}

if (!roteiro.scenes || !roteiro.scenes.length) throw new Error('MiniMax não gerou scenes');
if (!roteiro.intro_prompt) throw new Error('MiniMax não gerou intro_prompt');
if (!roteiro.outro_prompt) throw new Error('MiniMax não gerou outro_prompt');

console.log(`[${pid}] Roteiro OK: ${roteiro.scenes.length} cenas`);

return [{
  json: {
    production_id: pid,
    topic,
    scenes: roteiro.scenes,
    intro_narration: roteiro.intro_narration || '',
    outro_narration: roteiro.outro_narration || '',
    intro_prompt: roteiro.intro_prompt,
    outro_prompt: roteiro.outro_prompt,
    scene_count: roteiro.scenes.length,
  }
}];
